// Combina items RSS (con category) + entradas del log (isLogEntry=true)
const items = $input.all();

// 1. Enlaces ya publicados para no repetir
const logLinks = new Set(
  items
    .filter(i => i.json.isLogEntry === true && i.json.Link)
    .map(i => i.json.Link.trim())
);

// 2. Extraer última categoría publicada si existe en el log para evitar rachas
const logEntriesWithCat = items.filter(i => i.json.isLogEntry === true && (i.json.Category || i.json.category));
const lastCategory = logEntriesWithCat.length > 0 
  ? (logEntriesWithCat[logEntriesWithCat.length - 1].json.Category || logEntriesWithCat[logEntriesWithCat.length - 1].json.category)
  : null;

// 3. Filtrar noticias frescas
const freshItems = items.filter(i => {
  if (i.json.isLogEntry) return false;
  const link = (i.json.link || '').trim();
  return link && !logLinks.has(link);
});

if (freshItems.length === 0) {
  return [{ json: { found: false } }];
}

// 4. Agrupar noticias por categoría
const byCategory = {};
for (const item of freshItems) {
  const cat = item.json.category || 'Tecnología';
  if (!byCategory[cat]) byCategory[cat] = [];
  byCategory[cat].push(item);
}

// 5. Categorías disponibles
const availableCategories = Object.keys(byCategory);

// Si la última categoría fue por ejemplo 'IA', priorizar rotar a otra (Hardware, Ciberseguridad, Informática, etc.)
let eligibleCategories = availableCategories;
if (availableCategories.length > 1 && lastCategory) {
  const otherCategories = availableCategories.filter(c => c.toLowerCase() !== lastCategory.toLowerCase());
  if (otherCategories.length > 0) {
    eligibleCategories = otherCategories;
  }
}

// 6. Selección Estratificada Equitativa:
// Paso A: Sorteo de categoría con idéntica probabilidad para cada área
const chosenCategory = eligibleCategories[Math.floor(Math.random() * eligibleCategories.length)];
const categoryItems = byCategory[chosenCategory];

// Paso B: Dentro de la categoría elegida, sortear entre las 20 noticias más recientes
const pool = categoryItems.slice(0, 20);
const chosen = pool[Math.floor(Math.random() * pool.length)];

return [{
  json: {
    found: true,
    title: chosen.json.title || '',
    link: chosen.json.link || '',
    description: (chosen.json.contentSnippet || chosen.json.content || '').toString().substring(0, 500),
    category: chosenCategory,
    totalFreshInCategory: categoryItems.length,
    activeCategoriesCount: availableCategories.length
  }
}];

