const category = $('Select New Topic').item?.json?.category || 'Ciberseguridad';
const postText = $('Final Post Text').item?.json?.content || '';
const topic = $('Select New Topic').item?.json || {};
const title = topic.title || '';
const desc = topic.description || '';
const fullText = (title + ' ' + desc).toLowerCase();

// 1. Detección inteligente: ¿Es mejor Diagrama o Imagen Conceptual según la temática?
// Temas estructurales, protocolos, flujos, hardware, redes, topología o defensas se benefician de DIAGRAMA
const diagramKeywords = [
  'architecture', 'arquitectura', 'network', 'red', 'redes', 'routing', 'protocol', 'protocolo',
  'infrastructure', 'infraestructura', 'pipeline', 'cluster', 'kubernetes', 'k8s', 'docker', 'container',
  'firewall', 'topology', 'topología', 'hardware', 'chip', 'processor', 'procesador', 'semiconductor',
  'pcb', 'circuit', 'circuito', 'vulnerability', 'vulnerabilidad', 'exploit', 'cve', 'malware', 'attack',
  'api', 'framework', 'database', 'base de datos', 'server', 'servidor', 'sysadmin', 'kernel', 'linux',
  'backend', 'data flow', 'flujo', 'diagram', 'diagrama', 'esquemático', 'schematic'
];

const matchesDiagram = diagramKeywords.some(kw => fullText.includes(kw));

// 2. Foco temático abstracto SIN incluir el título de la noticia
const categoryConcepts = {
  "Ciberseguridad": "cybersecurity defense architecture, cryptographic verification layers, threat mitigation conduits",
  "Infraestructura": "cloud infrastructure cluster, high-availability data center routing, distributed system modules",
  "IA": "artificial intelligence neural compute core, deep learning tensor pipelines, high-dimensional data processing",
  "Hardening": "system hardening defense layout, multi-layered security controls, protected endpoint architecture",
  "Hardware": "advanced semiconductor microarchitecture, silicon die interconnects, precision electronic bus lines",
  "Informática": "enterprise computing network topology, high-throughput digital switching, modular server systems"
};

const conceptFocus = categoryConcepts[category] || categoryConcepts["Ciberseguridad"];

// 3. Catálogo de estilos según la modalidad elegida
const diagramStyles = [
  // Blueprint de arquitectura
  "technical architectural diagram, isometric system architecture blueprint, abstract interconnected data flow conduits and modular blocks, dark slate blueprint background with crisp cyan and gold lines, precision vector aesthetic, 8k resolution",
  // Topología de red y flujo
  "futuristic network topology diagram, clean flowchart data pipeline visualization, glowing abstract nodes and routing pathways, dark theme engineering graphic, minimal modern cyber schematic",
  // Esquemático de hardware y circuitos
  "precision technical schematic diagram, isometric micro-architecture and bus interconnects, sleek circuit blueprint layout, dark titanium background with luminous copper traces, modular system layout",
  // Infografía modular técnica
  "modern enterprise technology infographics diagram, abstract modular layers, secure pipeline architecture visualization, sleek dark glassmorphism surfaces and glowing geometric connections"
];

const imageStyles = [
  // Render 3D Isométrico de Alta Gama
  "sleek 3D isometric octane render, futuristic corporate tech aesthetic, slate and indigo background with glowing subtle nodes, clean geometric lighting, sophisticated studio environment",
  // Fotografía editorial tecnológica
  "high-end technology editorial photography, dramatic architectural lighting, clean minimal composition, deep navy and cyan highlights, 8k resolution, photorealistic",
  // Concepto abstracto minimalista
  "minimalist modern abstract concept, glowing subtle data streams and geometric grid, glass and dark titanium surfaces, elegant corporate tech style, photorealistic 8k",
  // Visual cinematográfico corporativo
  "cinematic corporate technology visual, deep obsidian palette, soft ambient illumination, macro depth of field, hyper-detailed digital surfaces"
];

let chosenMode = "";
let chosenStyle = "";

if (matchesDiagram) {
  chosenMode = "diagrama";
  chosenStyle = diagramStyles[Math.floor(Math.random() * diagramStyles.length)];
} else {
  chosenMode = "imagen_conceptual";
  chosenStyle = imageStyles[Math.floor(Math.random() * imageStyles.length)];
}

// 4. Prompt final para FLUX.1:
// ESTRICTO: SIN título de noticia, sin texto, sin letras, sin palabras escritas, sin etiquetas
const imagePrompt = `${conceptFocus}, ${chosenStyle}, strictly no text, no words, no letters, no labels, no title, no typography, no captions, no watermark, no logo, no distorted faces`;

return [{
  json: {
    ...$('Final Post Text').item.json,
    imagePrompt: imagePrompt,
    category: category,
    originalTitle: title,
    visualMode: chosenMode,
    visualStyleVariant: chosenStyle.substring(0, 50) + '...'
  }
}];

const input = $input.first();
const b64 = input?.json?.result?.image;

if (!b64) {
  throw new Error('No se recibió imagen base64 de Cloudflare Workers AI');
}

return [{
  json: {
    ...input.json,
    hasImage: true
  },
  binary: {
    data: {
      data: b64,
      mimeType: 'image/jpeg',
      fileName: 'flux_linkedin.jpg',
      fileExtension: 'jpg'
    }
  }
}];

